const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const escapeHtml = (v) => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl = (u) => {try {const url=new URL(u);return url.protocol==='https:'?escapeHtml(url.href):'#';}catch{return '#';}};
const read = (key, fallback) => {try{return JSON.parse(localStorage.getItem(key)) ?? fallback;}catch{return fallback;}};
const write = (key,value) => {try{localStorage.setItem(key,JSON.stringify(value));}catch{/* Browsing still works without persistence. */}};
const bookmarkIcon='<svg viewBox="0 0 18 22" aria-hidden="true"><path d="M3 2h12v18l-6-4-6 4Z"/></svg>';
const state={projects:[],topic:'全部',query:'',savedOnly:false,sort:'curated',view:'gallery',saved:new Set(read('xplore:saved',[]))};
const views={gallery:'A · 图文卡片',masonry:'B · 瀑布画廊',index:'C · 紧凑目录'};
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2800);}
function setView(view){if(!Object.hasOwn(views,view))return;state.view=view;document.body.dataset.view=view;$$('.demo-dock [data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===view)));const u=new URL(location.href);u.searchParams.set('view',view);history.replaceState({},'',u);updateChoice();}
function updateChoice(){const chosen=read('xplore:chosen-view',null)===state.view;$('#choose-view').textContent=chosen?'已选 ✓':'选这个 ↗';$('#choose-view').classList.toggle('chosen',chosen);}
function filters(){const topics=['全部',...new Set(state.projects.flatMap(p=>p.topics))];$('#filters').innerHTML=topics.map(t=>`<button data-topic="${escapeHtml(t)}" aria-pressed="${state.topic===t}">${escapeHtml(t)}</button>`).join('');}
function card(p,i){return `<article class="project-card" style="animation-delay:${Math.min(i,6)*35}ms" data-id="${escapeHtml(p.id)}"><button class="card-media" data-open="${escapeHtml(p.id)}" data-name="${escapeHtml(p.name)}" aria-label="查看 ${escapeHtml(p.name)} 的项目详情"><img src="${escapeHtml(p.image)}" alt="${escapeHtml(p.illustration?p.name+' 机制示意':p.name+' 官方项目图')}" loading="${i<2?'eager':'lazy'}" decoding="async"><span class="media-type">${p.illustration?'CONCEPT DIAGRAM':'PROJECT / DEMO'}</span><span class="open-circle" aria-hidden="true">↗</span></button><div class="card-content"><div class="card-meta"><span>${escapeHtml(p.topics[0])} <span aria-hidden="true">/</span> ${escapeHtml(p.status)}</span><button class="bookmark" data-save="${escapeHtml(p.id)}" aria-label="${state.saved.has(p.id)?'取消收藏':'收藏'} ${escapeHtml(p.name)}" aria-pressed="${state.saved.has(p.id)}">${bookmarkIcon}</button></div><div class="card-title"><h2>${escapeHtml(p.name)}</h2><span class="project-year">${p.year}</span></div><p class="card-kicker">${escapeHtml(p.title)}</p><p class="card-summary">${escapeHtml(p.summary)}</p><div class="card-bottom"><span class="card-team">${escapeHtml(p.team)}</span><button class="detail-link" data-open="${escapeHtml(p.id)}" aria-label="了解 ${escapeHtml(p.name)}">去看看 ↗</button></div></div></article>`;}
function render(){let ps=state.projects.filter(p=>(state.topic==='全部'||p.topics.includes(state.topic))&&(!state.savedOnly||state.saved.has(p.id))&&`${p.name} ${p.title} ${p.summary} ${p.team} ${p.topics.join(' ')}`.toLocaleLowerCase().includes(state.query.toLocaleLowerCase()));if(state.sort==='year')ps.sort((a,b)=>b.year-a.year);if(state.sort==='name')ps.sort((a,b)=>a.name.localeCompare(b.name));$('#projects').innerHTML=ps.map(card).join('');$('#empty').hidden=ps.length>0;$('#empty-note').textContent=state.savedOnly?'遇到喜欢的项目，点一下书签收进这里。':'换个关键词，或清除筛选再逛逛。';$('#total-count').textContent=String(ps.length).padStart(2,'0');$('#result-status').textContent=`显示 ${ps.length} 个项目`;$('#saved-count').textContent=state.saved.size;$('#saved-toggle').setAttribute('aria-pressed',String(state.savedOnly));$$('#filters button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.topic===state.topic)));$$('.card-media img').forEach(img=>{img.addEventListener('error',()=>img.parentElement.classList.add('image-failed'),{once:true});if(img.complete&&!img.naturalWidth)img.parentElement.classList.add('image-failed');});}
function openProject(id){const p=state.projects.find(x=>x.id===id);if(!p)return;const resources=[['原始项目',p.source],p.paper&&['阅读论文',p.paper],p.code&&['查看代码',p.code],!p.code&&['观看演示',p.demo]].filter(Boolean);$('#detail-body').innerHTML=`<img class="detail-img" src="${escapeHtml(p.image)}" alt="${escapeHtml(p.name)}"><div class="detail-inner"><p class="eyebrow">${escapeHtml(p.topics.join(' / '))} · ${p.year}</p><h2 id="detail-name">${escapeHtml(p.name)}</h2><p class="detail-title">${escapeHtml(p.title)}</p><p class="detail-text">${escapeHtml(p.summary)}</p>${[['有意思在哪里',p.why],['怎么做到的',p.how],['目前的边界',p.limit]].map(([label,t])=>`<div class="detail-block"><h3>${label}</h3><p class="detail-text">${escapeHtml(t)}</p></div>`).join('')}<div class="resource-links">${resources.map(([label,url])=>`<a href="${safeUrl(url)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`).join('')}</div><p class="detail-credit">${escapeHtml(p.imageCredit)}<br>${escapeHtml(p.team)}</p><p class="detail-dates">收录 ${escapeHtml(p.addedAt)} · 来源核验 ${escapeHtml(p.verifiedAt)}</p></div>`;$('#project-dialog').showModal();}
document.addEventListener('click',e=>{const open=e.target.closest('[data-open]');if(open){openProject(open.dataset.open);return;}const save=e.target.closest('[data-save]');if(save){const id=save.dataset.save;state.saved.has(id)?state.saved.delete(id):state.saved.add(id);write('xplore:saved',[...state.saved]);render();const fresh=$$('[data-save]').find(b=>b.dataset.save===id);fresh?.focus({preventScroll:true});return;}const filter=e.target.closest('[data-topic]');if(filter){state.topic=filter.dataset.topic;render();return;}const view=e.target.closest('.demo-dock [data-view]');if(view){setView(view.dataset.view);return;}if(e.target.closest('.subscribe-trigger')){const d=$('#subscribe-dialog');$('#subscribe-form').hidden=false;$('#subscribe-result').hidden=true;$('#email').value='';d.showModal();return;}if(e.target.closest('.dialog-close'))e.target.closest('dialog').close();});
$('#search').addEventListener('input',e=>{state.query=e.target.value;render();});$('#sort').addEventListener('change',e=>{state.sort=e.target.value;render();});$('#saved-toggle').addEventListener('click',()=>{state.savedOnly=!state.savedOnly;render();$('#collection').scrollIntoView({behavior:'smooth'});});$('#reset-filters').addEventListener('click',()=>{state.topic='全部';state.query='';state.savedOnly=false;$('#search').value='';render();});$('#choose-view').addEventListener('click',()=>{write('xplore:chosen-view',state.view);updateChoice();toast(`已在本机记下：${views[state.view]}。在对话中告诉我即可继续。`);});$('#subscribe-form').addEventListener('submit',e=>{e.preventDefault();if(!e.target.reportValidity())return;$('#email').value='';e.target.hidden=true;$('#subscribe-result').hidden=false;});$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}));document.addEventListener('keydown',e=>{if(e.key==='/'&&!e.metaKey&&!e.ctrlKey&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&!$('dialog[open]')){e.preventDefault();$('#search').focus();}});
try{const response=await fetch('projects.json');if(!response.ok)throw new Error('collection unavailable');const data=await response.json();if(!Array.isArray(data))throw new Error('invalid collection');state.projects=data;state.saved=new Set([...state.saved].filter(id=>data.some(p=>p.id===id)));filters();setView(new URL(location.href).searchParams.get('view')||'gallery');render();}catch{$('#projects').innerHTML='<p class="loading">收藏集暂时未能打开。请刷新重试。</p>';}
